VALUES(content_id, '9688cd08-adef-408c-9d34-5d75ae5c44df', content_type_field_name_id, 'Can [childFirstName] follow simple directions (e.g., “Stand up" or "Come here”)?', null, null, CURRENT_DATE, CURRENT_DATE);  

